const detailDialog=document.querySelector('#detail-dialog');
function showDialog(dialog){dialog.showModal();document.body.classList.add('modal-open');}
document.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>{const d=details[button.dataset.detail];document.querySelector('#dialog-content').innerHTML=`<img class="detail-image" src="assets/${d.image}.jpg" alt="${d.title}"><div class="detail-body"><p class="eyebrow">${d.category}</p><h2 id="dialog-title">${d.title}</h2><p>${d.text}</p>${d.facts?`<div class="detail-facts">${d.facts.map(f=>`<span>${f}</span>`).join('')}</div>`:''}<ul>${d.features.map(f=>`<li>${f}</li>`).join('')}</ul><p class="demo-note">Вигаданий портфолійний приклад. Усі характеристики, послуги та ціни є демонстраційними.</p><a class="button dialog-book" href="#availability">Обрати дати <span aria-hidden="true">↗</span></a></div>`;detailDialog.querySelector('.dialog-book').addEventListener('click',()=>{detailDialog.close();document.querySelector('#check-in').focus({preventScroll:true});});showDialog(detailDialog);}));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));dialog.addEventListener('click',e=>{const rect=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom))dialog.close();});});
const photos=[['mountains','Карпати в ранковому тумані'],['forest','Затишний гостьовий номер'],['restaurant','Деталі ресторанного сервірування'],['spa','Простір для відновлення'],['terrace','Світлий простір біля тераси']];
let photoIndex=0;const galleryDialog=document.querySelector('#gallery-dialog');
function renderPhoto(){const [file,caption]=photos[photoIndex];const img=document.querySelector('#gallery-image');img.src=`assets/${file}.jpg`;img.alt=caption;document.querySelector('#gallery-caption').textContent=`${caption} · ${photoIndex+1} / ${photos.length}`;}
function stepPhoto(n){photoIndex=(photoIndex+n+photos.length)%photos.length;renderPhoto();}
document.querySelectorAll('[data-gallery]').forEach(b=>b.addEventListener('click',()=>{photoIndex=Number(b.dataset.gallery);renderPhoto();showDialog(galleryDialog);}));
document.querySelector('#gallery-prev').addEventListener('click',()=>stepPhoto(-1));document.querySelector('#gallery-next').addEventListener('click',()=>stepPhoto(1));
galleryDialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();stepPhoto(-1);}if(e.key==='ArrowRight'){e.preventDefault();stepPhoto(1);}});
document.querySelectorAll('[data-social]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#dialog-content').innerHTML='<div class="detail-body"><p class="eyebrow">ПОРТФОЛІЙНА КОНЦЕПЦІЯ</p><h2 id="dialog-title">Залишаймося на зв’язку</h2><p>Це демонстраційна іконка соціальної мережі. Maison Aurelle — вигаданий готель, тому реальних соціальних сторінок у цього проєкту немає.</p></div>';showDialog(detailDialog);}));
const form=document.querySelector('#availability-form'),checkIn=document.querySelector('#check-in'),checkOut=document.querySelector('#check-out'),message=document.querySelector('#form-message');
function localDate(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function nextDate(value){const date=new Date(`${value}T12:00:00`);date.setDate(date.getDate()+1);return localDate(date);}
const today=localDate(new Date());checkIn.min=today;checkOut.min=nextDate(today);
checkIn.addEventListener('change',()=>{checkOut.min=checkIn.value?nextDate(checkIn.value):nextDate(today);});
form.addEventListener('input',()=>{message.hidden=true;form.querySelectorAll('[aria-invalid]').forEach(f=>f.removeAttribute('aria-invalid'));});
form.addEventListener('submit',e=>{e.preventDefault();let error='';let field;
if(!checkIn.value){error='Оберіть дату заїзду.';field=checkIn;}else if(checkIn.value<localDate(new Date())){error='Дата заїзду не може бути в минулому.';field=checkIn;}else if(!checkOut.value){error='Оберіть дату виїзду.';field=checkOut;}else if(checkOut.value<=checkIn.value){error='Дата виїзду має бути пізнішою за дату заїзду.';field=checkOut;}
message.hidden=false;message.classList.toggle('error',!!error);
if(error){message.textContent=error;field.setAttribute('aria-invalid','true');field.focus();return;}
const format=new Intl.DateTimeFormat('uk-UA',{day:'numeric',month:'long',year:'numeric'});const from=format.format(new Date(`${checkIn.value}T12:00:00`));const to=format.format(new Date(`${checkOut.value}T12:00:00`));
message.textContent=`Ви обрали ${from} — ${to}, гостей: ${document.querySelector('#guests').value}. Це портфолійна демоформа: доступність не перевіряється, дані не надсилаються, бронювання не створюється. Для реального бронювання потрібно було б звернутися до готелю. Maison Aurelle та наведені контакти вигадані.`;message.focus();});
